(() => {
  const config = window.BLACKOUT_SUPABASE;
  const root = document.querySelector('#admin-root');
  const toastNode = document.querySelector('#admin-toast');
  const SESSION_KEY = 'blackout-admin-session';
  const modules = [
    ['dashboard','⌂','Dashboard'],['products','▦','Produtos'],['categories','◇','Categorias'],['stock','▤','Estoque'],
    ['orders','⬡','Pedidos'],['customers','♙','Clientes'],['services','⚙','Serviços'],['offers','％','Ofertas'],
    ['banners','▧','Banners'],['settings','⚙','Configurações']
  ];
  let session = null;
  let currentUser = null;

  const escapeHtml = value => String(value ?? '').replace(/[&<>'"]/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
  const money = value => Number(value || 0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
  const dateTime = value => value ? new Date(value).toLocaleString('pt-BR',{dateStyle:'short',timeStyle:'short'}) : '—';
  const toast = message => { toastNode.textContent=message;toastNode.classList.add('show');setTimeout(()=>toastNode.classList.remove('show'),2400) };

  async function request(path,{method='GET',body,token=session?.access_token,headers={}}={}){
    const response=await fetch(`${config.url}${path}`,{method,headers:{apikey:config.publishableKey,Authorization:`Bearer ${token||config.publishableKey}`,'Content-Type':'application/json',...headers},body:body===undefined?undefined:JSON.stringify(body)});
    const text=await response.text();let data=null;try{data=text?JSON.parse(text):null}catch{data=text}
    if(!response.ok){const error=new Error(data?.msg||data?.message||data?.error_description||'request_failed');error.status=response.status;throw error}
    return data;
  }

  function persistSession(value){session=value;if(value)localStorage.setItem(SESSION_KEY,JSON.stringify(value));else localStorage.removeItem(SESSION_KEY)}
  function readSession(){try{return JSON.parse(localStorage.getItem(SESSION_KEY)||'null')}catch{return null}}
  function consumeAuthCallback(){const params=new URLSearchParams(location.hash.slice(1));const accessToken=params.get('access_token');const refreshToken=params.get('refresh_token');if(!accessToken||!refreshToken)return null;const value={access_token:accessToken,refresh_token:refreshToken,expires_in:Number(params.get('expires_in')||3600),token_type:params.get('token_type')||'bearer',expires_at:Date.now()+Number(params.get('expires_in')||3600)*1000};persistSession(value);history.replaceState({},'',location.pathname);return {type:params.get('type')||'invite'}}
  async function refreshSession(){if(!session?.refresh_token)throw new Error('no_refresh_token');const data=await request('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:{refresh_token:session.refresh_token},token:config.publishableKey});data.expires_at=Date.now()+Number(data.expires_in||3600)*1000;persistSession(data);return data}
  async function getUser(){if(!session?.access_token)return null;if(session.expires_at&&session.expires_at<Date.now()+30000)await refreshSession();try{return await request('/auth/v1/user')}catch(error){if(error.status===401){await refreshSession();return request('/auth/v1/user')}throw error}}
  async function checkAdmin(user){const rows=await request(`/rest/v1/admin_users?select=user_id&user_id=eq.${encodeURIComponent(user.id)}`);return Array.isArray(rows)&&rows.length===1}

  function setPath(path){history.replaceState({},'',path)}
  function renderLogin(message=''){
    setPath('/admin/login/');
    root.innerHTML=`<section class="login-page"><div class="login-brand"><div class="brand-lockup"><span class="brand-title">BLAC<i>◉</i>OUT</span><span class="brand-sub">INFOR GAMES</span></div><div class="login-brand-copy"><span>Gestão segura</span><h1>CONTROLE TOTAL DA OPERAÇÃO</h1><p>Produtos, pedidos e estoque em uma área administrativa separada da experiência dos clientes.</p></div><div class="login-security">Acesso protegido pelo Supabase Auth e pelas políticas de segurança do banco.</div></div><div class="login-panel"><form id="login-form" class="login-card"><span class="eyebrow">Área administrativa</span><h2>ENTRAR NO PAINEL</h2><p>Use o e-mail autorizado para administrar a BLACKOUT.</p><div class="field"><label for="admin-email">E-mail</label><input id="admin-email" name="email" type="email" autocomplete="username" required></div><div class="field"><label for="admin-password">Senha</label><input id="admin-password" name="password" type="password" autocomplete="current-password" minlength="6" required></div><button class="admin-primary" type="submit">Entrar</button><button class="admin-link" id="recover-password" type="button">Recuperar senha</button><div id="login-error" class="form-error ${message?'show':''}">${escapeHtml(message)}</div></form></div></section>`;
    document.querySelector('#login-form').addEventListener('submit',handleLogin);
    document.querySelector('#recover-password').addEventListener('click',handleRecovery);
  }

  async function handleLogin(event){event.preventDefault();const form=event.currentTarget;const button=form.querySelector('.admin-primary');const errorNode=form.querySelector('#login-error');button.disabled=true;button.textContent='Entrando…';errorNode.classList.remove('show');try{const data=await request('/auth/v1/token?grant_type=password',{method:'POST',body:{email:form.email.value.trim(),password:form.password.value},token:config.publishableKey});data.expires_at=Date.now()+Number(data.expires_in||3600)*1000;persistSession(data);currentUser=data.user;if(!await checkAdmin(currentUser)){persistSession(null);renderUnauthorized();return}setPath('/admin/');renderShell();await loadDashboard();toast('Acesso autorizado')}catch(error){errorNode.textContent=error.status===400?'E-mail ou senha inválidos.':'Não foi possível entrar. Tente novamente.';errorNode.classList.add('show');button.disabled=false;button.textContent='Entrar'}}
  async function handleRecovery(){const email=document.querySelector('#admin-email').value.trim();const errorNode=document.querySelector('#login-error');if(!email){errorNode.textContent='Informe seu e-mail para recuperar a senha.';errorNode.classList.add('show');return}try{await request('/auth/v1/recover',{method:'POST',body:{email,redirect_to:`${location.origin}/admin/`},token:config.publishableKey});toast('Confira seu e-mail para redefinir a senha')}catch{errorNode.textContent='Não foi possível enviar a recuperação. Tente novamente.';errorNode.classList.add('show')}}

  function renderUnauthorized(){setPath('/admin/login/');root.innerHTML=`<section class="unauthorized"><strong>ACESSO BLOQUEADO</strong><p>Este usuário está autenticado, mas não possui permissão administrativa para acessar a operação da BLACKOUT.</p><button class="admin-primary" id="back-login">Voltar ao login</button></section>`;document.querySelector('#back-login').onclick=async()=>{persistSession(null);renderLogin()}}
  function renderPasswordSetup(type){root.innerHTML=`<section class="login-page"><div class="login-brand"><div class="brand-lockup"><span class="brand-title">BLAC<i>◉</i>OUT</span><span class="brand-sub">INFOR GAMES</span></div><div class="login-brand-copy"><span>Acesso protegido</span><h1>${type==='recovery'?'RECUPERE SEU ACESSO':'ATIVE SEU PAINEL'}</h1><p>Defina uma senha forte para concluir a configuração da sua conta administrativa.</p></div><div class="login-security">A senha é enviada diretamente ao Supabase e nunca passa por outro servidor.</div></div><div class="login-panel"><form id="password-form" class="login-card"><span class="eyebrow">Segurança da conta</span><h2>DEFINIR SENHA</h2><p>Use pelo menos oito caracteres.</p><div class="field"><label for="new-password">Nova senha</label><input id="new-password" name="password" type="password" autocomplete="new-password" minlength="8" required></div><div class="field"><label for="confirm-password">Confirmar senha</label><input id="confirm-password" name="confirmPassword" type="password" autocomplete="new-password" minlength="8" required></div><button class="admin-primary" type="submit">Salvar e entrar</button><div id="password-error" class="form-error"></div></form></div></section>`;document.querySelector('#password-form').addEventListener('submit',handlePasswordSetup)}
  async function handlePasswordSetup(event){event.preventDefault();const form=event.currentTarget;const errorNode=form.querySelector('#password-error');const button=form.querySelector('.admin-primary');if(form.password.value!==form.confirmPassword.value){errorNode.textContent='As senhas não coincidem.';errorNode.classList.add('show');return}button.disabled=true;button.textContent='Salvando…';try{await request('/auth/v1/user',{method:'PUT',body:{password:form.password.value}});currentUser=await getUser();if(!await checkAdmin(currentUser)){renderUnauthorized();return}setPath('/admin/');renderShell();await loadDashboard();toast('Senha definida e acesso liberado')}catch{errorNode.textContent='Não foi possível definir a senha. Solicite um novo convite.';errorNode.classList.add('show');button.disabled=false;button.textContent='Salvar e entrar'}}

  function navMarkup(){return modules.map(([id,icon,label])=>`<button data-admin-view="${id}" class="${id==='dashboard'?'active':''}"><span>${icon}</span>${label}</button>`).join('')}
  function renderShell(){root.innerHTML=`<div class="sidebar-backdrop" data-close-menu></div><div class="admin-shell"><aside class="admin-sidebar"><div class="sidebar-brand"><strong>BLAC<i>◉</i>OUT</strong><small>PAINEL ADMIN</small></div><nav class="admin-nav" aria-label="Navegação administrativa">${navMarkup()}</nav><div class="sidebar-bottom"><div class="admin-account"><strong>Administrador</strong><small>${escapeHtml(currentUser?.email||'')}</small></div><button class="signout" id="admin-signout">Sair com segurança</button></div></aside><section class="admin-main"><header class="admin-topbar"><button class="menu-toggle" aria-label="Abrir menu">☰</button><div><h1>Visão geral</h1><p>Operação BLACKOUT em tempo real</p></div><span class="admin-badge">● Ambiente protegido</span></header><div id="admin-content" class="admin-content">${dashboardSkeleton()}</div></section></div>`;bindShell()}
  function bindShell(){document.querySelector('.menu-toggle').onclick=()=>toggleMenu(true);document.querySelector('[data-close-menu]').onclick=()=>toggleMenu(false);document.querySelector('#admin-signout').onclick=signOut;document.querySelectorAll('[data-admin-view]').forEach(button=>button.onclick=()=>selectView(button.dataset.adminView))}
  function toggleMenu(open){document.querySelector('.admin-sidebar').classList.toggle('open',open);document.querySelector('.sidebar-backdrop').classList.toggle('open',open)}
  function selectView(view){toggleMenu(false);document.querySelectorAll('[data-admin-view]').forEach(button=>button.classList.toggle('active',button.dataset.adminView===view));if(view==='dashboard'){document.querySelector('.admin-topbar h1').textContent='Visão geral';loadDashboard();return}const label=modules.find(item=>item[0]===view)?.[2]||'Módulo';document.querySelector('.admin-topbar h1').textContent=label;document.querySelector('#admin-content').innerHTML=`<section class="admin-card module-placeholder"><span>◇</span><h2>${escapeHtml(label.toUpperCase())}</h2><p>Este módulo será conectado ao Supabase na próxima etapa, sem alterar o funcionamento do site público.</p></section>`}
  function dashboardSkeleton(){return `<div class="content-head"><div><h2>DASHBOARD</h2><p>Carregando indicadores reais da loja…</p></div></div><div class="kpi-grid">${Array.from({length:4},()=>'<div class="admin-kpi skeleton"><div class="skeleton-line"></div><div class="skeleton-line big"></div><div class="skeleton-line"></div></div>').join('')}</div><div class="dashboard-grid"><div class="admin-card skeleton"><div class="skeleton-line big"></div>${Array.from({length:4},()=>'<div class="skeleton-line"></div>').join('')}</div><div class="admin-card skeleton"><div class="skeleton-line big"></div>${Array.from({length:4},()=>'<div class="skeleton-line"></div>').join('')}</div></div>`}
  async function loadDashboard(){const container=document.querySelector('#admin-content');if(!container)return;container.innerHTML=dashboardSkeleton();try{const metrics=await request('/rest/v1/rpc/admin_dashboard_metrics',{method:'POST',body:{}});renderDashboard(metrics||{})}catch(error){container.innerHTML=`<section class="admin-card module-placeholder"><span>!</span><h2>DADOS INDISPONÍVEIS</h2><p>${error.status===404?'Execute a migration administrativa para ativar as métricas reais.':'Não foi possível carregar o dashboard. Verifique a conexão e tente novamente.'}</p><button class="admin-primary" id="retry-dashboard" style="max-width:240px;margin:12px auto">Tentar novamente</button></section>`;document.querySelector('#retry-dashboard').onclick=loadDashboard}}
  function renderDashboard(metrics){const orders=Array.isArray(metrics.recent_orders)?metrics.recent_orders:[];const low=Array.isArray(metrics.low_stock_products)?metrics.low_stock_products:[];document.querySelector('#admin-content').innerHTML=`<div class="content-head"><div><h2>DASHBOARD</h2><p>Indicadores calculados diretamente no Supabase.</p></div><span class="date-chip">Atualizado ${new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}</span></div><div class="kpi-grid"><article class="admin-kpi cyan"><small>FATURAMENTO</small><strong>${money(metrics.revenue)}</strong><span>Pedidos pagos ou concluídos</span></article><article class="admin-kpi green"><small>PEDIDOS</small><strong>${Number(metrics.orders_total||0)}</strong><span>${Number(metrics.orders_pending||0)} pendentes</span></article><article class="admin-kpi orange"><small>ESTOQUE BAIXO</small><strong>${Number(metrics.low_stock||0)}</strong><span>Produtos no limite mínimo</span></article><article class="admin-kpi red"><small>SERVIÇOS</small><strong>${Number(metrics.services_in_progress||0)}</strong><span>Módulo ainda não cadastrado</span></article></div><div class="dashboard-grid"><section class="admin-card"><div class="card-head"><h3>Pedidos recentes</h3><span>${orders.length} exibidos</span></div>${orders.length?`<div class="data-list">${orders.map(order=>`<div class="data-row"><div><strong>Pedido #${escapeHtml(order.id)}</strong><small>${escapeHtml(order.customer_name)} • ${dateTime(order.created_at)}</small></div><div class="data-value"><strong>${money(order.total)}</strong><span class="pill">${escapeHtml(order.status)}</span></div></div>`).join('')}</div>`:'<div class="empty-state"><strong>Nenhum pedido recebido</strong><span>Os pedidos reais aparecerão aqui.</span></div>'}</section><section class="admin-card"><div class="card-head"><h3>Estoque baixo</h3><span>${low.length} produtos</span></div>${low.length?`<div class="data-list">${low.map(product=>`<div class="data-row"><div><strong>${escapeHtml(product.name)}</strong><small>Mínimo: ${Number(product.stock_min||0)}</small></div><div class="data-value"><strong>${Number(product.stock||0)} un.</strong><span class="pill warn">Repor</span></div></div>`).join('')}</div>`:'<div class="empty-state"><strong>Estoque saudável</strong><span>Nenhum produto abaixo do mínimo.</span></div>'}</section></div>`}
  async function signOut(){try{if(session?.access_token)await request('/auth/v1/logout',{method:'POST'})}catch{}persistSession(null);currentUser=null;renderLogin('Sessão encerrada com segurança.')}
  async function init(){if(!config){root.textContent='Configuração do Supabase não encontrada.';return}const callback=consumeAuthCallback();if(callback){renderPasswordSetup(callback.type);return}session=readSession();if(!session){renderLogin();return}try{currentUser=await getUser();if(!currentUser){persistSession(null);renderLogin();return}if(!await checkAdmin(currentUser)){renderUnauthorized();return}setPath('/admin/');renderShell();await loadDashboard()}catch{persistSession(null);renderLogin('Sua sessão expirou. Entre novamente.')}}
  init();
})();
